<template>
  <section v-loading="loading" class="gift-panel">
    <div class="heading"><div><h3>赠品与售后处理</h3><p>赠送资格、实际发货和退回入账分别记录。已发赠品不会因退款直接恢复库存。</p></div><el-button size="small" @click="load">刷新赠品进度</el-button></div>
    <el-alert v-if="row.block_reason" :title="row.block_reason" type="warning" :closable="false" show-icon/>
    <el-empty v-if="!row.available || !(row.lines||[]).length" description="本订单没有 OMS 策略赠品"/>
    <template v-else>
      <div v-for="l in row.lines" :key="l.id" class="gift-card">
        <div class="gift-title"><div><strong>{{ l.goods_name }}</strong><div class="muted">{{ l.sku_sn }} · OMS 赠品明细 #{{ l.id }} · 不占用平台子单号</div></div><el-tag :type="['WAIT_CANCEL','WAIT_CUTOFF','WAIT_RETURN','PENDING_REVIEW'].includes(l.gift_state)?'warning':'success'">{{ labels[l.gift_state] || l.gift_state }}</el-tag></div>
        <p class="muted">{{ origins(l.sku_sn) }}</p>
        <div class="numbers"><div>原赠送<strong>{{ l.quantity }} 件</strong></div><div>当前可保留<strong>{{ l.eligible_quantity }} 件</strong></div><div>已发 / 已取消<strong>{{ l.shipped_quantity }} / {{ l.cancelled_quantity }} 件</strong></div><div>待取消 / 待退回<strong>{{ l.cancel_required }} / {{ l.return_required }} 件</strong></div><div>已退入账 / 已豁免<strong>{{ l.returned_quantity }} / {{ l.waived_quantity }} 件</strong></div></div>
        <p v-if="l.pending_assessment" class="forecast">售后申请尚未确认：预计可保留 {{ l.projected_eligible_quantity }} 件；此时仅暂缓，不直接取消或追退。</p>
        <div class="next"><span>下一步：{{ l.next_action }}</span><div><el-button v-if="l.cancel_required>0" v-hasPermi="['order:gift:execute']" size="small" type="primary" :loading="saving" @click="cancel(l)">{{ l.needs_cutoff?'撤回相关发货单':'取消失效赠品' }}</el-button><el-button v-if="l.unarranged_quantity>0" v-hasPermi="['order:gift:execute']" size="small" type="primary" @click="startReturn(l)">安排赠品退回</el-button><el-button v-if="l.unarranged_quantity>0" v-hasPermi="['order:gift:waive']" size="small" @click="startWaive(l)">豁免追退</el-button></div></div>
        <div v-if="(l.return_plans||[]).length" class="returns"><h4>关联退回安排</h4><div v-for="p in l.return_plans" :key="p.id" class="return-row"><span>安排 #{{ p.id }} · 计划 {{ p.quantity }} · 实收 {{ p.accepted_quantity }} · 已入账 {{ p.posted_quantity }}</span><div><el-button v-if="!p.actual&&p.state==='PLANNED'" v-hasPermi="['order:gift:execute']" type="text" @click="runReturn(p,'dispatch')">下发仓库</el-button><el-button v-if="p.actual" v-hasPermi="['order:gift:execute']" type="text" @click="runReturn(p,'query')">核对仓库原单</el-button><el-button v-if="p.actual&&p.accepted_quantity>p.posted_quantity" v-hasPermi="['order:gift:execute']" type="text" @click="runReturn(p,'posting')">核对实收入账</el-button><el-button type="text" @click="goRefund(p.refund_id)">包裹、THK 与截单</el-button></div></div></div>
      </div>
      <el-collapse><el-collapse-item title="赠品资格计算依据与处理记录" name="evidence"><el-alert title="采用下单时的策略版本，只核对原赠品权益；不会因售后重新参加其他活动。退差价是否影响金额门槛以原策略配置为准。" :closable="false" type="info"/><el-table :data="row.effective_basis"><el-table-column prop="platform_oid" label="原平台子单" min-width="190"/><el-table-column prop="sku_sn" label="购买 SKU"/><el-table-column prop="quantity" label="售后后有效数量"/><el-table-column prop="payment" label="门槛计算金额"/></el-table><el-table :data="row.events"><el-table-column prop="create_time" label="时间" width="170"/><el-table-column prop="actor" label="操作人" width="130"/><el-table-column prop="message" label="记录" min-width="400"/></el-table></el-collapse-item></el-collapse>
    </template>
    <el-dialog title="安排赠品退回" :visible.sync="returnVisible" width="750px" append-to-body :close-on-click-modal="false">
      <el-alert title="按赠品原出库来源创建退回安排。相同运单、地址等满足店铺规则时，可与正品共用退回包裹及 THK；创建安排不增加库存。" type="info" :closable="false" show-icon/>
      <el-form label-width="125px" size="small" style="margin-top:18px"><el-form-item label="关联退款单" required><el-select v-model="form.refund_id" style="width:100%" @change="options"><el-option v-for="r in eligibleRefunds" :key="r.id" :value="r.id" :label="r.refund_sn"/></el-select></el-form-item><el-form-item label="原发货明细" required><el-select v-model="form.shipment_line_id" style="width:100%"><el-option v-for="s in selected.sources||[]" :key="s.id" :value="s.id" :label="`${s.shipment_sn} · 明细 #${s.id} · 已发 ${s.shipped_quantity} 件`"/></el-select></el-form-item><el-form-item label="本次退回数量" required><el-input-number v-model="form.quantity" :min="1" :max="Number(selected.unarranged_quantity||1)" :precision="0"/></el-form-item><el-form-item label="退回仓" required><el-select v-model="form.store_code" style="width:100%"><el-option v-for="w in warehouses" :key="w.code" :value="w.code" :label="`${w.name} (${w.code})`"/></el-select></el-form-item><el-form-item label="退回地址" required><el-input v-model="form.return_address" maxlength="500"/></el-form-item><el-form-item label="退回联系人" required><el-input v-model="form.return_contact" maxlength="200"/></el-form-item><el-form-item label="处理依据" required><el-input v-model="form.reason" type="textarea" maxlength="500"/></el-form-item><el-form-item label="协商凭证" required><el-input v-model="form.evidence" type="textarea" maxlength="1000"/></el-form-item><el-form-item><el-checkbox v-model="form.confirmed">已确认赠品退回范围和原发货来源</el-checkbox></el-form-item></el-form>
      <span slot="footer"><el-button @click="returnVisible=false">取消</el-button><el-button type="primary" :disabled="!form.confirmed" :loading="saving" @click="createReturn">创建退回安排</el-button></span>
    </el-dialog>
    <el-dialog title="豁免赠品追退" :visible.sync="waiveVisible" width="600px" append-to-body :close-on-click-modal="false"><el-alert title="豁免表示确认不再追回，不代表实收，不增加库存，也不调整平台退款金额。" type="warning" :closable="false"/><el-form label-width="100px" style="margin-top:18px"><el-form-item label="豁免数量"><el-input-number v-model="waiver.quantity" :min="1" :max="Number(selected.unarranged_quantity||1)" :precision="0"/></el-form-item><el-form-item label="原因" required><el-input v-model="waiver.reason" type="textarea" maxlength="500"/></el-form-item><el-form-item label="审批凭证" required><el-input v-model="waiver.evidence" type="textarea" maxlength="1000"/></el-form-item><el-checkbox v-model="waiver.confirmed">确认不再追回上述数量</el-checkbox></el-form><span slot="footer"><el-button @click="waiveVisible=false">取消</el-button><el-button type="primary" :disabled="!waiver.confirmed" :loading="saving" @click="waive">确认豁免</el-button></span></el-dialog>
  </section>
</template>
<script>
import * as api from '@/api/order/gift'
const labels={WAIT_STOCK:'赠品库存不足，待补货',ELIGIBLE:'赠送资格有效',PENDING_REVIEW:'售后待确认，暂缓赠送',WAIT_CANCEL:'失效赠品待取消',WAIT_CUTOFF:'待撤回后取消',WAIT_RETURN:'已发赠品待退回',RETURNING:'赠品退回处理中',RETURNED:'赠品已退入账',WAIVED:'已豁免追退',CANCELED:'失效赠品已取消'}
export default { props:{orderId:[Number,String]},data:()=>({loading:false,saving:false,sequence:0,row:{},labels,selected:{},form:{},waiver:{},returnVisible:false,waiveVisible:false,warehouses:[]}),computed:{eligibleRefunds(){return (this.row.triggers||[]).filter(r=>r.review_state==='APPROVED')}},watch:{orderId:{immediate:true,handler(){this.load()}}},methods:{async load(){if(!this.orderId)return;const seq=++this.sequence;this.loading=true;try{const result=(await api.orderGifts(this.orderId)).data;if(seq===this.sequence)this.row=result}finally{if(seq===this.sequence)this.loading=false}},origins(sku){return ((this.row.snapshot||{}).entitlements||[]).filter(g=>g.sku_sn===sku).map(g=>`${g.group_name} / ${g.rule_name}：${g.quantity} 件`).join('；')},async cancel(l){await this.$confirm(l.needs_cutoff?'将撤回包含赠品的相关发货单。仓库确认后取消失效赠品，剩余正品需重新分仓。':'确认取消失效赠品并核对原库存占用？','处理失效赠品',{type:'warning'});this.saving=true;try{const r=(await api.cancelGift(this.orderId,{control_version:this.row.control_version,order_line_id:l.id})).data;this.$message.success(r.message||'赠品取消已完成');await this.load();this.$emit('changed')}finally{this.saving=false}},async startReturn(l){this.selected=l;this.form={gift_plan_id:this.row.id,quantity:Number(l.unarranged_quantity),shipment_line_id:(l.sources||[])[0]&&l.sources[0].id,refund_id:this.eligibleRefunds[0]&&this.eligibleRefunds[0].id,reason:'售后后不再满足原赠送条件',evidence:'',request_key:`GIFT_${Date.now()}_${Math.random().toString(36).slice(2,10)}`,confirmed:false};this.returnVisible=true;await this.options()},async options(){this.warehouses=this.form.refund_id?(await api.giftReturnOptions(this.form.refund_id)).data.warehouses:[]},async createReturn(){if(!this.form.reason||!this.form.evidence||!this.form.store_code||!this.form.return_address||!this.form.return_contact||!this.form.refund_id)return this.$message.warning('请补全退回来源、地址和协商凭证');this.saving=true;try{const refund=this.eligibleRefunds.find(r=>r.id===this.form.refund_id);await api.createGiftReturn(this.form.refund_id,{...this.form,control_version:refund.control_version});this.returnVisible=false;this.$message.success('赠品退回安排已创建；请核对包裹及 THK 下发进度');await this.load();this.$emit('changed')}finally{this.saving=false}},startWaive(l){this.selected=l;this.waiver={order_line_id:l.id,quantity:Number(l.unarranged_quantity),reason:'',evidence:'',confirmed:false};this.waiveVisible=true},async waive(){if(!this.waiver.reason||!this.waiver.evidence)return this.$message.warning('请填写原因和审批凭证');this.saving=true;try{await api.waiveGift(this.orderId,{...this.waiver,control_version:this.row.control_version});this.waiveVisible=false;this.$message.success('已豁免追退，库存未增加');await this.load();this.$emit('changed')}finally{this.saving=false}},goRefund(id){this.$router.push({path:'/oms-order/businessRefunds',query:{id}})},async runReturn(p,action){this.saving=true;try{const refund=(this.row.triggers||[]).find(r=>r.id===p.refund_id)||{};await api.giftReturnAction(p.refund_id,p.id,p.actual?p.actual.id:0,action,{control_version:refund.control_version,plan_version:p.control_version});this.$message.success(action==='dispatch'?'已提交仓库，请核对原单结果':'已核对原仓库结果');await this.load();this.$emit('changed')}finally{this.saving=false}}} }
</script>
<style scoped>.gift-panel{margin:20px 0}.heading,.gift-title,.next,.return-row{display:flex;justify-content:space-between;align-items:center;gap:16px}.heading h3{margin:0}.heading p,.muted{color:#8491a3;font-size:12px;line-height:1.8}.gift-card{border:1px solid #dfe6ef;border-radius:8px;margin:16px 0;padding:20px;overflow-wrap:anywhere}.gift-title strong{font-size:16px}.numbers{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;background:#f5f8fc;padding:16px;color:#8190a4;font-size:12px}.numbers strong{display:block;color:#26364a;font-size:17px;margin-top:6px}.next{margin-top:16px;font-size:13px;color:#435570}.forecast{padding:10px;background:#fff8e9;color:#986818;font-size:13px}.returns{border-top:1px solid #edf0f5;margin-top:16px}.return-row{padding:8px 0;font-size:13px}@media(max-width:1000px){.numbers{grid-template-columns:repeat(3,1fr)}.next,.return-row{align-items:flex-start;flex-direction:column}}</style>
